import{_ as a,c as s,o as e,a4 as i,a5 as t,a6 as o}from"./chunks/framework.ssOvXUgL.js";const m=JSON.parse('{"title":"Docker 部署","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/install/docker.md","filePath":"deploy/install/docker.md","lastUpdated":1728809929000}'),d={name:"deploy/install/docker.md"},h=i(`<h1 id="docker-部署" tabindex="-1">Docker 部署 <a class="header-anchor" href="#docker-部署" aria-label="Permalink to &quot;Docker 部署&quot;">​</a></h1><h2 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h2><p>首先你需要安装 docker 服务，包括 <code>docker</code> 与 <code>docker-compose</code>。参考<a href="https://www.docker.com/get-started/" target="_blank" rel="noreferrer">官方文档</a></p><p>在此种部署方式中，你无需自行启动 <code>redis</code> 服务，docker 将会附带启动一个 <code>redis</code> 容器。</p><h2 id="拉取项目" tabindex="-1">拉取项目 <a class="header-anchor" href="#拉取项目" aria-label="Permalink to &quot;拉取项目&quot;">​</a></h2><p>与<a href="./manual.html">手动部署</a>相同的步骤</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://mirror.ghproxy.com/https://github.com/SilveryStar/Adachi-BOT.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Adachi-BOT</span></span></code></pre></div><h2 id="初次启动项目" tabindex="-1">初次启动项目 <a class="header-anchor" href="#初次启动项目" aria-label="Permalink to &quot;初次启动项目&quot;">​</a></h2><p>通过 <code>docker-compose</code> 直接以 <code>docker</code> 方式启动项目</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><h2 id="修改配置文件" tabindex="-1">修改配置文件 <a class="header-anchor" href="#修改配置文件" aria-label="Permalink to &quot;修改配置文件&quot;">​</a></h2><p>与手动部署一样，初次运行将在根目录 <code>config</code> 文件夹下生成配置文件模板，需要自行对修改配置文件内容。</p><p>不同的是，当使用本地自建的 <code>OneBot</code> 实现时，<code>config/base.yml =&gt; wsServer</code> 中的 ip 部分不能使用 <code>localhost</code> 或 <code>127.0.0.1</code>。</p><p>首先检查 Docker 版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>若为 <code>18.03</code> 以上，可以使用 <code>host.docker.internal</code> 来替代 ip 部分，例如: <code>host.docker.internal:8080</code>。</p><p>反之需要根据不同环境按照以下方式手动获取主机地址</p><h3 id="linux" tabindex="-1">linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;linux&quot;">​</a></h3><p>查看网关信息</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ifconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><p>结果中 <code>inet</code> 后即为主机地址</p><p><img src="`+t+'" alt="eth0"></p><h3 id="windows" tabindex="-1">windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;windows&quot;">​</a></h3><p>查看网关信息</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipconfig</span></span></code></pre></div><p>在结果中查找 <code>以太网适配器 vEthernet (WSL):</code> 开头的一项，使用 <code>IPv4 地址</code> 作为主机地址</p><p><img src="'+o+'" alt="WSL"></p><h2 id="再次启动项目" tabindex="-1">再次启动项目 <a class="header-anchor" href="#再次启动项目" aria-label="Permalink to &quot;再次启动项目&quot;">​</a></h2><p>修改配置文件完毕后，执行命令重启项目。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><p>若未正常启动，可执行下方命令来查看错误信息</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker-compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div>',32),p=[h];function l(n,c,r,k,g,b){return e(),s("div",null,p)}const F=a(d,[["render",l]]);export{m as __pageData,F as default};
